import * as THREE from 'three';
import {createArcheryModel} from './archery-model.js';
import {createArcherySession,fitArcheryCamera} from './archery-session.js';
export const ARCHERY_BODY=`<div class="gym-layout"><div class="gym-court archery-court" id="archery-court" role="img" aria-label="도름이의 활과 화살, 과녁이 보이는 양궁 연습장. 화면을 끌어 조준하고 놓으면 쏴요" tabindex="0"></div><section class="gym-panel archery-panel" id="archery-panel"><p id="archery-status" role="status"></p><div class="gym-actions"><button id="archery-start">다섯 발 연습 시작</button><button id="archery-pause">잠깐 쉬기</button><button id="archery-exit">멈추고 나오기</button></div><label>좌우 조준 <input id="archery-yaw" type="range" min="-0.16" max="0.16" step="0.005" value="-0.13"></label><label>위아래 조준 <input id="archery-pitch" type="range" min="-0.04" max="0.22" step="0.005" value="0.14"></label><div class="gym-hold"><button id="archery-hold">누르고 당겼다 놓기</button></div><p id="archery-power"></p><p id="archery-score" role="status"></p><details id="archery-help"><summary>조작 안내</summary><p>화면을 끌어 조준하고 놓거나, 조준 슬라이더를 움직인 뒤 아래 버튼을 누르고 놓아요. 키보드 방향키로 조준하고 스페이스를 눌렀다 놓아도 돼요.</p><p>길게 누르기 어렵다면 버튼에 초점을 맞춰 Enter로 당기기를 시작하고 Enter를 다시 눌러 쏘세요. 힘은 약 1초에 가득 차요. 날아간 화살이 실제로 닿은 과녁만 점수가 돼요.</p><p>혼자 다섯 발을 연습해요. 중간에 나와도 괜찮아요. 보상이나 저장 기록은 없어요. 화면을 벗어나면 멈추고 계속하기를 눌러야 이어져요.</p></details></section></div>`;
export function createArcheryController({ui,getView,getActors,stage,isAllowed=()=>true,onChange=()=>{},clearInput=()=>{},doc=globalThis.document,win=globalThis.window,sessionFactory=createArcherySession,modelFactory=createArcheryModel,fitCamera=fitArcheryCamera}){
 const camera=new THREE.OrthographicCamera(),$=id=>doc.querySelector('#'+id);let live=null,pending=false,generation=0;
 function listen(node,type,fn,opts){if(!node)return;node.addEventListener(type,fn,opts);live.listeners.push([node,type,fn,opts]);}
 function clear(){clearInput();if(!live)return;live.pointers.clear();live.keys.clear();live.drag=null;live.model.setInput({cancel:true});}
 function held(){if(live&&live.pointers.size+live.keys.size>0)live.model.setInput({held:true});}
 function render(){if(!live)return;const s=live.model.snapshot(),p=live.session.phase,paused=live.suspended||s.paused,ready=live.session.ready&&['idle','ready','stopped'].includes(s.state),active=s.state==='active'&&!paused&&!live.exiting;$('archery-status').textContent=paused?'멈췄어요. 계속하기를 누르면 이어져요':p==='boarding'?'양궁 자리로 걸어가요':p==='guarding'?'두 발을 딛고 활을 준비해요':p==='lowering'||p==='exiting'?'활을 내려놓고 천천히 걸어 나와요':live.exiting?'화살이 멈춘 뒤 나와요':ready?'준비됐어요. 시작은 직접 골라요':s.arrow?'화살이 날아가요':s.held?'활시위를 당기고 있어요':'조준하고 활시위를 당겨 보세요';$('archery-score').textContent=`${s.shots} / 5발 · ${s.score}점`;$('archery-power').textContent=s.state==='stopped'?'이번 연습을 마쳤어요':`당긴 힘 ${Math.round(s.draw*100)}%`;$('archery-start').disabled=!ready||paused||live.exiting;$('archery-start').textContent=s.state==='stopped'?'다섯 발 다시 연습':'다섯 발 연습 시작';$('archery-pause').textContent=paused?'계속하기':'잠깐 쉬기';$('archery-exit').disabled=live.exiting;$('archery-hold').disabled=!active||!!s.arrow;for(const [id,k]of[['archery-yaw','yaw'],['archery-pitch','pitch']]){$(id).disabled=!active||!!s.arrow;$(id).value=String(s[k]);}}
 function clean({restore}={}){pending=false;generation++;if(!live)return;const old=live;live=null;old.observer?.disconnect();for(const[n,t,f,o]of old.listeners)n.removeEventListener(t,f,o);old.model.dispose?.();old.session.dispose({restore:restore??(getView()===old.source)});stage.classList.remove('gym-open');doc.body?.classList.remove('gym-open');clearInput();onChange();}
 function cancel(){const owned=!!live||pending;clean();if(owned)ui.close();}
 function close(){if(!live||live.exiting)return;clear();live.suspended=false;live.model.resume();live.exiting=true;live.model.stop('exit');live.session.requestExit();render();}
 function pause(){if(!live)return;clear();live.suspended=true;live.model.pause();live.session.pause?.();render();}
 function open(){if(live||pending||!isAllowed())return false;const source=getView();if(!source?.schoolView?.gymView?.archery)return false;pending=true;const token=++generation;
 const accepted=ui.workshop('양궁 · 혼자 다섯 발 연습',ARCHERY_BODY,()=>{if(token!==generation||!pending)return;if(getView()!==source){pending=false;return;}pending=false;let session;try{session=sessionFactory({view:source,...getActors()});live={session,model:modelFactory(),source,listeners:[],pointers:new Set(),keys:new Set(),suspended:false,exiting:false,fit:''};stage.classList.add('gym-open');doc.body?.classList.add('gym-open');clearInput();onChange();
  const act=(id,fn)=>listen($(id),'click',e=>{if(token!==generation||!live||$(id).disabled)return;if(e.detail>0&&live.cancelledPointer)return;e.preventDefault();fn();});
  act('archery-start',()=>{clear();if(live.session.ready)live.model.start();render();});act('archery-exit',close);act('archery-pause',()=>{if(doc.hidden)return;if(live.suspended||live.model.snapshot().paused){clear();live.suspended=false;live.model.resume();render();}else pause();});
  for(const [id,key]of[['archery-yaw','yaw'],['archery-pitch','pitch']])listen($(id),'input',()=>{if(!live||$(id).disabled)return;live.model.setInput({[key]:Number($(id).value)});render();});
  const button=$('archery-hold'),court=$('archery-court');
  for(const node of[button,court]){
   listen(node,'pointerdown',e=>{const s=live?.model.snapshot();if(!live||live.exiting||live.suspended||s.state!=='active'||s.paused||s.arrow||e.button!==0||e.isPrimary===false||live.pointers.size)return;e.preventDefault();live.cancelledPointer=false;node.setPointerCapture?.(e.pointerId);live.pointers.add(e.pointerId);live.drag={id:e.pointerId,node,x:e.clientX??0,y:e.clientY??0,yaw:s.yaw,pitch:s.pitch};held();render();});
   listen(node,'pointermove',e=>{if(!live||node!==court||live.drag?.id!==e.pointerId)return;const d=live.drag,b=court.getBoundingClientRect();live.model.setInput({yaw:d.yaw+((e.clientX??d.x)-d.x)/Math.max(1,b.width)*.32,pitch:d.pitch-((e.clientY??d.y)-d.y)/Math.max(1,b.height)*.26});render();});
   for(const type of['pointerup','pointercancel','lostpointercapture'])listen(node,type,e=>{if(!live||!live.pointers.has(e.pointerId))return;live.pointers.delete(e.pointerId);live.drag=null;if(type==='pointerup')live.model.setInput({release:true});else{live.cancelledPointer=true;live.model.setInput({cancel:true});}render();});
  }
  listen(button,'click',e=>{if(!live||button.disabled||e.detail>0)return;e.preventDefault();live.model.setInput(live.model.snapshot().held?{release:true}:{held:true});render();});
  listen(doc,'keydown',e=>{if(!live||e.repeat||e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const control=e.target?.closest?.('button,a,summary,[role="button"]')??(['BUTTON','A','SUMMARY'].includes(e.target?.tagName)?e.target:null);if(control&&control!==button)return;const s=live.model.snapshot();if(live.suspended||s.paused||live.exiting||s.state!=='active'||s.arrow)return;if(e.code==='Space'){e.preventDefault();live.keys.add(e.code);held();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code)){e.preventDefault();live.model.setInput(e.code==='ArrowLeft'?{yaw:s.yaw-.01}:e.code==='ArrowRight'?{yaw:s.yaw+.01}:e.code==='ArrowUp'?{pitch:s.pitch+.01}:{pitch:s.pitch-.01});render();}});
  listen(doc,'keyup',e=>{if(live&&live.keys.has(e.code)){e.preventDefault();live.keys.delete(e.code);live.model.setInput({release:true});render();}});
  listen($('archery-panel'),'pointerdown',()=>{if(live)live.cancelledPointer=false;},true);listen($('archery-panel'),'pointercancel',()=>{if(live)live.cancelledPointer=true;},true);
  const modal=$('modal'),exit=modal?.querySelector?.('[data-close]');if(exit)exit.onclick=e=>{e.preventDefault();close();};listen(modal,'cancel',e=>{e.preventDefault();close();});listen(modal,'click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation?.();}},true);
  listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(win,'pagehide',cancel);const resize=()=>{if(live&&token===generation)viewport(stage.clientWidth,stage.clientHeight);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('archery-court'));}render();resize();$('archery-court').focus();return()=>{if(token===generation)clean();};
 }catch(error){if(live)clean();else session?.dispose();pending=false;ui.close();ui.toast('양궁 자리까지 빈 길이 필요해요. 잠깐 뒤 다시 해 주세요');}},{kind:'gym-workshop archery-workshop',closeLabel:'멈추고 나오기'});if(!accepted&&token===generation)pending=false;return accepted;}
 function runtimeFailure(){const restore=!!live&&getView()===live.source;clean({restore});ui.close();ui.toast('양궁 연습을 멈췄어요. 잠깐 뒤 다시 해 주세요');}
 function tick(dt){if(!live)return;if(getView()!==live.source){clean({restore:false});ui.close();return;}try{const s=live.model.snapshot();if(!live.suspended&&!s.paused){if(live.session.ready&&s.state==='idle')live.model.ready();live.session.tick(dt,live.model);if(live.session.ready&&live.model.snapshot().state==='idle')live.model.ready();}if(live.session.done){clean();ui.close();return;}render();}catch(error){runtimeFailure();}}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('archery-court').getBoundingClientRect(),a=stage.getBoundingClientRect(),rect={x:Math.max(0,b.left-a.left),y:Math.max(0,b.top-a.top),width:Math.max(1,Math.min(b.width,width)),height:Math.max(1,Math.min(b.height,height))},key=Object.values(rect).join(',')+','+['ready','exercise'].includes(live.session.phase);if(key!==live.fit){try{fitCamera(camera,live.session.root,rect,{active:['ready','exercise'].includes(live.session.phase)});live.fit=key;}catch(error){runtimeFailure();}}return rect;}
 return{open,close,cancel,pause,tick,viewport,camera,dispose:cancel,get active(){return!!live;},snapshot:()=>live?{...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused,session:live.session.snapshot(),exiting:live.exiting}:null};
}
